// Reusable generic polymorphic component typing
// @see https://confluence.airbus.corp/x/I3NYEg

type PropsWithComponent<C extends React.ElementType> = {
  /** The component to be used as a root node */
  component?: C;
};

// utility to omit duplicated props from source/target
type PropsToOmit<
  C extends React.ElementType,
  T
> = keyof (PropsWithComponent<C> & T);

/**
 * polymorphic component prop
 * will add `component` and `children` prop types
 */
export type PolymorphicProps<
  C extends React.ElementType,
  SourceProps = {}
> = React.PropsWithChildren<PropsWithComponent<C> & SourceProps> &
  Omit<React.ComponentPropsWithoutRef<C>, PropsToOmit<C, SourceProps>>;

/**
 * polymorphic component prop (with ref)
 */
export type PolymorphicPropsWithRef<
  C extends React.ElementType,
  SourceProps
> = PolymorphicProps<C, SourceProps> & { ref?: PolymorphicRef<C> };

/**
 * polymorphic ref utility
 */
export type PolymorphicRef<C extends React.ElementType> =
  React.ComponentPropsWithRef<C>["ref"];
